const state={session:null,bookings:[],expenses:[],calendar:[],customers:[],campaigns:[],referrals:{rewards:[]},view:initialAdminView,filter:'all',detail:null,listScroll:0,clientSort:'last',clientSegment:'all',analyticsPeriod:'30',analyticsMonth:'',analyticsYear:'',analyticsProductMetric:'count',analyticsTrendMetric:'revenue',expenseCategory:'all',health:null,rememberSession:sessionPersistent(),upcomingScope:'all',lastError:null};
const todayIso=()=>{const d=new Date(),pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`};
const dayDiff=value=>{if(!value)return 0;const today=Date.parse(todayIso()+'T12:00:00Z'),target=Date.parse(String(value).slice(0,10)+'T12:00:00Z');return Math.round((target-today)/86400000)};
const COMPLETED_VISIBLE_DAYS=14,DAY_MS=24*60*60*1000;
function completionMoment(b){const raw=b?.completed_at||b?.extras?.settlement?.completed_at||b?.updated_at||(b?.return_date?`${b.return_date}T23:59:59`:''),stamp=Date.parse(raw);return Number.isFinite(stamp)?stamp:0}
function isRecentCompleted(b,now=Date.now()){return b?.status==='completed'&&completionMoment(b)>now-COMPLETED_VISIBLE_DAYS*DAY_MS}
function isFinishedCompleted(b,now=Date.now()){return b?.status==='completed'&&!isRecentCompleted(b,now)}
function scheduleMeta(b){const eventDate=b.status==='issued'?b.return_date:b.start_date,diff=dayDiff(eventDate),isReturn=b.status==='issued';if(['completed','cancelled','declined'].includes(b.status))return{className:'muted',label:b.status==='completed'?'Завершено':'Неактивне',diff,eventDate};if(diff<0)return{className:'danger',label:isReturn?'Повернення прострочено':'Дата минула',diff,eventDate};if(diff===0)return{className:'today',label:isReturn?'Повернення сьогодні':'Видача сьогодні',diff,eventDate};if(diff===1)return{className:'soon',label:isReturn?'Повернення завтра':'Видача завтра',diff,eventDate};return{className:'future',label:`Через ${diff} дн.`,diff,eventDate}}
function attentionSummary(){const today=todayIso(),active=state.bookings.filter(b=>!['completed','cancelled','declined'].includes(b.status));return{pending:active.filter(b=>b.status==='pending').length,waiting:active.filter(b=>b.status==='waiting_payment').length,issuesToday:active.filter(b=>['waiting_payment','confirmed'].includes(b.status)&&b.start_date===today).length,returnsToday:active.filter(b=>b.status==='issued'&&b.return_date===today).length,overdue:active.filter(b=>scheduleMeta(b).className==='danger').length}}
function operationsBar(){const x=attentionSummary(),returnClass=x.overdue?'danger':'return';return`<section class="operations-bar" aria-label="Потребує уваги"><button class="operation-card new" data-op-filter="pending"><span>Нові заявки</span><strong>${x.pending}</strong><small>${x.pending?'Опрацювати зараз':'Усе розібрано'}</small></button><button class="operation-card waiting" data-op-filter="waiting_payment"><span>Очікують оплату</span><strong>${x.waiting}</strong><small>${x.waiting?'Потрібне підтвердження':'Немає очікувань'}</small></button><button class="operation-card issue" data-op-scope="today"><span>Видачі сьогодні</span><strong>${x.issuesToday}</strong><small>Відкрити розклад</small></button><button class="operation-card ${returnClass}" data-op-scope="${x.overdue?'overdue':'today'}"><span>${x.overdue?'Прострочені події':'Повернення сьогодні'}</span><strong>${x.overdue||x.returnsToday}</strong><small>${x.overdue?'Потребують дії':'Відкрити розклад'}</small></button></section>`}
function bindOperations(){$$('[data-op-filter]').forEach(btn=>btn.onclick=()=>{state.filter=btn.dataset.opFilter;renderBookings();resetViewScroll()});$$('[data-op-scope]').forEach(btn=>btn.onclick=()=>{state.upcomingScope=btn.dataset.opScope||'all';switchView('upcoming',{clearSearch:true})})}
function instagramHandle(value){return String(value||'').trim().replace(/^@/,'').replace(/^https?:\/\/(?:www\.)?instagram\.com\//i,'').split(/[/?#]/)[0].replace(/[^A-Za-z0-9._]/g,'')}
function instagramContactLink(value){const handle=instagramHandle(value);return handle?`https://www.instagram.com/${encodeURIComponent(handle)}/`:'https://www.instagram.com/direct/inbox/'}
function referralShareText(referral){const code=String(referral?.code||'').trim();return `Дякуємо, що обираєте VAcleaner 🤍\n\nПриведіть друга — бонус отримають обоє.\nВаш код: ${code}\n\nДруг отримає −100 грн на першу оренду, а після завершення його оренди вам активується −150 грн на наступну.\n\nКожен зароблений бонус −150 грн діє 150 днів з моменту активації. Можете рекомендувати VAcleaner кільком друзям — за кожного нового клієнта отримаєте окремий бонус.\n\nКод можна використати при онлайн-бронюванні або просто надіслати нам у Direct Instagram.`}
function referralReminderText(reward){const end=new Date(reward?.expires_at||0),label=Number.isFinite(end.getTime())?new Intl.DateTimeFormat('uk-UA',{day:'numeric',month:'long'}).format(end):'дати завершення';return `VAcleaner 🤍 Нагадуємо: у вас залишився бонус −150 грн на наступну оренду за рекомендацію друга.\n\nВін діє до ${label} включно.\n\nЯкщо давно планували освіжити диван, матрац чи зробити прибирання — саме час використати бонус 🙂\n\nЗабронювати: vacleaner.pp.ua/bronuvannia/`}
async function sendReferralChannel({phone,instagram,telegram,preferredContact,referral,reward=null,channel}){const text=reward?referralReminderText(reward):referralShareText(referral);try{await navigator.clipboard.writeText(text)}catch{};const use=channel||preferredContact||((instagram)?'instagram':'telegram');if(use==='instagram')window.open(instagramContactLink(instagram),'_blank','noopener,noreferrer');else window.open(telegramContactLink({customer_phone:phone,customer_telegram:telegram}),'_blank','noopener,noreferrer');toast(`${use==='instagram'?'Instagram':'Telegram'} відкрито · текст скопійовано. Після фактичної відправки підтвердіть це в адмінці.`,'success');return use}
async function markReferralSent({phone,channel,reward=null}){await invoke({action:'referral_mark_sent',phone,channel,rewardId:reward?.id||'',confirmed:true});return true}
function bindReferralSendButton(btn,args){if(!btn)return;let opened=false,chosen=args.channel||'';btn.onclick=async()=>{if(btn.disabled)return;if(!opened){try{chosen=await sendReferralChannel(args);opened=true;btn.dataset.referralConfirm='1';btn.textContent='Позначити надісланим';btn.classList.add('primary')}catch(err){toast(err.message)}return}btn.disabled=true;try{await markReferralSent({phone:args.phone,channel:chosen,reward:args.reward});btn.textContent='Надіслано ✓';toast('Відправлення підтверджено','success')}catch(err){btn.disabled=false;toast(err.message)}}}
function referralExpiryAlert(){const rows=state.referrals?.rewards||[];if(!rows.length)return'';const first=rows[0],days=Math.max(0,Math.ceil((new Date(first.expires_at).getTime()-Date.now())/86400000));return`<section class="referral-expiry-alert"><button type="button" id="openReferralExpiry"><span><b>Бонуси скоро спливають</b><small>${rows.length} ${rows.length===1?'бонус':'бонусів'} · найближчий через ${days} дн.</small></span><strong>−150 грн</strong><i>›</i></button></section>`}
function bindReferralExpiry(){const btn=$('#openReferralExpiry');if(btn)btn.onclick=()=>openReferralExpiryList()}
function openReferralExpiryList(){const rows=state.referrals?.rewards||[];modal(`<div class="modal-form referral-expiry-modal"><header><div><small>Приведи друга</small><h2>Бонуси скоро спливають</h2><p>За 30 днів до завершення. Відкриття чату ще не рахується відправленням — підтвердіть після того, як реально надішлете повідомлення.</p></div><button class="close" type="button" data-close>×</button></header><div class="referral-expiry-list">${rows.map(r=>{const c=r.customer||{},days=Math.max(0,Math.ceil((new Date(r.expires_at).getTime()-Date.now())/86400000));return`<article><div><strong>${h(c.name||r.referrer_phone)}</strong><span>${h(r.referrer_phone)} · до ${dateFullNumeric(String(r.expires_at).slice(0,10))} · ${days} дн.</span></div><b>−${money(r.amount||150)}</b><div class="referral-send-actions">${c.instagram?`<button class="btn" data-ref-remind="instagram" data-id="${h(r.id)}">Instagram</button>`:''}<button class="btn" data-ref-remind="telegram" data-id="${h(r.id)}">Telegram</button></div></article>`}).join('')||'<div class="empty">Немає бонусів, що спливають.</div>'}</div></div>`);$$('[data-ref-remind]').forEach(btn=>{const r=rows.find(x=>x.id===btn.dataset.id);if(!r)return;const c=r.customer||{};bindReferralSendButton(btn,{phone:r.referrer_phone,instagram:c.instagram,telegram:c.telegram,preferredContact:c.preferred_contact,referral:null,reward:r,channel:btn.dataset.refRemind})})}
async function openReferralShare(b){const phone=normalizePhone(b?.customer_phone);if(!phone)return toast('У клієнта немає коректного номера');let data;try{data=await invoke({action:'referral_summary',phone})}catch(e){return toast(e.message)}const r=data?.referral;if(!r?.code)return toast('Код з’явиться після завершеної оренди');const profile=r.profile||{},preferred=profile.preferred_contact||b.preferred_contact||'phone';modal(`<div class="modal-form referral-share-modal"><header><div><small>Приведи друга</small><h2>${h(b.customer_name||profile.name||'Клієнт')}</h2><p>Персональний код безстроковий. Зароблений бонус −150 грн діє 150 днів.</p></div><button class="close" type="button" data-close>×</button></header><div class="referral-share-card"><span>Код клієнта</span><strong>${h(r.code)}</strong><small>Друг −100 грн · клієнт −150 грн після завершення оренди друга</small></div><div class="referral-share-stats"><span>${r.completedReferrals||0} завершених рекомендацій</span><span>${r.activeRewardCount||0} активних бонусів</span></div><div class="referral-message-preview">${h(referralShareText(r)).replace(/\n/g,'<br>')}</div><footer><button class="btn" type="button" data-close>Закрити</button>${profile.instagram||b.customer_instagram?'<button class="btn" id="sendReferralInstagram" type="button">Instagram · надіслати</button>':''}<button class="btn primary" id="sendReferralTelegram" type="button">Telegram · надіслати</button></footer></div>`);bindReferralSendButton($('#sendReferralInstagram'),{phone,instagram:profile.instagram||b.customer_instagram,telegram:profile.telegram||b.customer_telegram,preferredContact:preferred,referral:r,channel:'instagram'});bindReferralSendButton($('#sendReferralTelegram'),{phone,instagram:profile.instagram||b.customer_instagram,telegram:profile.telegram||b.customer_telegram,preferredContact:preferred,referral:r,channel:'telegram'})}
function queueBookingDeepLink(id){if(!validBookingId(id))return;pendingBookingId=id;openPendingBooking()}
function openPendingBooking(){if(!validBookingId(pendingBookingId)||!state.bookings.length||!document.querySelector('.app'))return;const id=pendingBookingId,b=state.bookings.find(item=>item.id===id);pendingBookingId='';cleanBookingUrl();if(!b){toast('Бронювання зі сповіщення не знайдено','warning');return}state.view='bookings';state.filter='all';const search=$('#globalSearch');if(search)search.value='';$('#clearSearch')?.classList.add('hidden');$$('.nav button[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view==='bookings'));render();resetViewScroll();requestAnimationFrame(()=>openDetail(b))}
function setConnectionState(){const e=$('#connectionState');if(!e)return;const online=navigator.onLine;e.className=`connection-state ${online?'online':'offline'}`;e.innerHTML=`<i></i><span>${online?'Онлайн':'Офлайн'}</span>`;e.title=online?'З’єднання із сервером доступне':'Немає з’єднання. Дані не змінюватимуться.'}
function renderLoading(){const view=$('#view');if(!view)return;view.setAttribute('aria-busy','true');view.innerHTML=`<div class="loading-shell"><div class="skeleton-ops">${Array.from({length:4},()=>'<i></i>').join('')}</div>${Array.from({length:3},()=>'<article class="card skeleton-card"><i></i><b></b><span></span><span></span></article>').join('')}</div>`}
function renderLoadError(error){state.lastError=error;const view=$('#view');if(!view)return;view.removeAttribute('aria-busy');view.innerHTML=`<div class="card load-state"><div class="load-state-icon">${navigator.onLine?'!':'⌁'}</div><h2>${navigator.onLine?'Не вдалося оновити дані':'Ви офлайн'}</h2><p>${h(error?.message||'Спробуйте ще раз за кілька секунд.')}</p><div><button class="btn primary" id="retryLoad">Спробувати ще раз</button></div><small>Вхід збережено. Повторно вводити пароль не потрібно.</small></div>`;$('#retryLoad').onclick=async()=>{renderLoading();try{await loadGlobalSlots();await load();render();toast('Дані оновлено','success')}catch(e){if(e.status===401){clearSession();auth()}else renderLoadError(e)}}}
function clearSession(){state.session=null;localStorage.removeItem(ADMIN_ALIAS_KEY);for(const store of [localStorage,sessionStorage]){store.removeItem(SESSION_KEY);store.removeItem(SESSION_SEEN)}}
async function logoutCurrentDevice(button){
  if(button?.disabled||!confirm('Вийти з акаунта на цьому пристрої?'))return;
  const session=getSession();
  if(button){button.disabled=true;button.classList.add('is-loading');const label=button.querySelector('span');if(label)label.textContent='Виходимо…'}
  try{
    if(session?.access_token&&navigator.onLine)await fetch(SUPABASE+'/auth/v1/logout?scope=local',{method:'POST',headers:{Authorization:`Bearer ${session.access_token}`,apikey:KEY}});
  }catch(error){console.warn('local_logout_failed',error)}
  finally{clearSession();location.reload()}
}
function getSession(){try{const persistent=sessionPersistent(),primary=persistent?localStorage:sessionStorage,fallback=persistent?sessionStorage:localStorage;let raw=primary.getItem(SESSION_KEY),seen=Number(primary.getItem(SESSION_SEEN)||0);if(!raw){raw=fallback.getItem(SESSION_KEY);if(raw){seen=Number(fallback.getItem(SESSION_SEEN)||0);primary.setItem(SESSION_KEY,raw);primary.setItem(SESSION_SEEN,String(seen||Date.now()));fallback.removeItem(SESSION_KEY);fallback.removeItem(SESSION_SEEN)}}if(!raw)return null;if(seen&&Date.now()-seen>SESSION_IDLE_MS){clearSession();return null}if(!seen||Date.now()-seen>SESSION_TOUCH_MS)primary.setItem(SESSION_SEEN,String(Date.now()));return JSON.parse(raw)}catch{clearSession();return null}}
function saveSession(s,persistent=state.rememberSession){state.session=s;state.rememberSession=persistent!==false;localStorage.setItem(SESSION_PREF,state.rememberSession?'1':'0');const primary=state.rememberSession?localStorage:sessionStorage,fallback=state.rememberSession?sessionStorage:localStorage;primary.setItem(SESSION_KEY,JSON.stringify(s));primary.setItem(SESSION_SEEN,String(Date.now()));fallback.removeItem(SESSION_KEY);fallback.removeItem(SESSION_SEEN)}
async function login(email,password){const r=await fetch(SUPABASE+'/auth/v1/token?grant_type=password',{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({email,password})});const d=await r.json();if(!r.ok)throw new Error('Невірний логін або пароль');return d}
async function refreshNetwork(session){const s=session||getSession();if(!s?.refresh_token){const e=new Error('Сесія завершена');e.status=401;throw e}let r;try{r=await fetch(SUPABASE+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:s.refresh_token})})}catch{const e=new Error(navigator.onLine?'Не вдалося зв’язатися із сервером':'Немає інтернету');e.status=0;throw e}const d=await r.json().catch(()=>({}));if(!r.ok){const e=new Error('Сесія завершена');e.status=r.status;e.code=d.error||'session_expired';throw e}saveSession(d,sessionPersistent());return d}
async function refresh(){if(refreshPromise)return refreshPromise;const initial=getSession(),initialAccess=initial?.access_token||'';refreshPromise=(async()=>{const run=async()=>{const latest=getSession();if(latest?.access_token&&latest.access_token!==initialAccess)return latest;return refreshNetwork(latest||initial)};if(sessionPersistent()&&navigator?.locks?.request)return navigator.locks.request('vacleaner-auth-refresh',{mode:'exclusive'},run);return run()})();try{return await refreshPromise}finally{refreshPromise=null}}
async function invokeAt(endpoint,body,retry=true){let s=getSession();if(!s?.access_token){const e=new Error('Сесія завершена');e.status=401;throw e}let r;try{r=await fetch(endpoint,{method:'POST',headers:{Authorization:`Bearer ${s.access_token}`,apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify(body)})}catch{const e=new Error(navigator.onLine?'Не вдалося зв’язатися із сервером. Перевірте мережу й повторіть.':'Немає інтернету. Дані не змінено.');e.status=0;throw e}if(r.status===401&&retry){await refresh();return invokeAt(endpoint,body,false)}const d=await r.json().catch(()=>({error:'service_error'}));if(!r.ok){const labels={service_error:'Сервіс тимчасово недоступний',unauthorized:'Сесія завершена',forbidden:'Немає доступу до адмінки',inventory_conflict:'Цей слот уже зайнятий',invalid_extension:'Нова дата повернення має бути пізнішою за поточну',extension_only_for_issued:'Продовжити можна лише видану оренду',customer_phone_exists:'Клієнт із таким номером уже існує',invalid_customer_data:'Перевірте ПІБ і номер телефону',invalid_campaign:'Перевірте параметри кампанії',invalid_expense:'Перевірте дату, категорію та суму витрати',expense_not_found:'Витрату вже архівовано або не знайдено',invalid_promo_code:'Промокод має містити щонайменше 4 символи',promo_code_exists:'Такий промокод уже існує',no_eligible_customers:'Немає клієнтів, які відповідають умовам RETURN-кампанії',customer_not_found:'Клієнта з таким номером ще немає в базі',bonus_not_issued:'Цьому клієнту ще не була видана персональна пропозиція через SMS',activation_window_expired:'Строк активації цього бонусу вже завершився',promo_used:'Цей бонус уже використано',promo_unavailable:'Бонус уже недоступний',campaign_has_history:'Кампанію вже використовували — її можна лише архівувати',campaign_archived:'Архівовану кампанію не можна знову увімкнути',sendpulse_not_configured:'Ключ SendPulse не налаштований',sender_not_active:'VACLEANER ще не активований для національних SMS. Оберіть міжнародний маршрут або дочекайтесь модерації.',invalid_sms_campaign:'Оберіть одержувачів і перевірте текст SMS',sms_too_long:'SMS завелика — максимум 402 Unicode-символи',sms_optout_required:'У рекламній SMS має бути коротке посилання для відмови: vacleaner.pp.ua/s',legacy_consent_confirmation_required:'Для старої бази потрібно окремо підтвердити право на відправку',audience_changed:'Список змінився. Оновіть аудиторію перед відправкою.',sendpulse_api_error:'SendPulse не прийняв розсилку.',sendpulse_preflight_failed:'SendPulse відхилив перевірку розсилки.',invalid_dispatch:'Розсилку не знайдено',promo_link_required:'У SMS цієї кампанії має залишитися {link} — система автоматично підставить посилання з промокодом.',promo_codes_missing:'У кампанії немає доступного активного промокоду для цієї відправки. Оновіть аудиторію або перевірте коди кампанії.',campaign_inactive:'Кампанія вже не активна — SMS з її промокодами не надсилаємо.',self_referral:'Свій referral-код використати не можна',referral_first_rental_only:'Код друга діє тільки на першу оренду нового клієнта',referral_already_used:'Для цього номера referral-бонус уже був використаний або заброньований',referral_inactive:'Цей код «Приведи друга» більше не активний',invalid_referral:'Перевірте код «Приведи друга»',referral_reward_unavailable:'Referral-бонус уже використаний або сплив',invalid_referral_contact:'Оберіть Instagram або Telegram для повідомлення'};const base=labels[d.error]||d.error||'Помилка сервера',detail=typeof d.detail==='string'&&d.detail?String(d.detail).replace(/^sendpulse_http_\d+:/,'').replace(/^sendpulse_preflight_rejected:/,'').slice(0,220):'';const e=new Error(detail?`${base} ${detail}`:base);e.status=r.status;e.code=d.error||'service_error';e.detail=detail;throw e}return d}
