function withUiTimeout(promise,ms=15000,message='Сервіс відповідає надто довго. Спробуйте ще раз.'){let timer=0;const timeout=new Promise((_,reject)=>{timer=window.setTimeout(()=>{const e=new Error(message);e.status=0;reject(e)},ms)});return Promise.race([promise,timeout]).finally(()=>{if(timer)window.clearTimeout(timer)})}
