const DOCUMENT_MAX_BYTES=8*1024*1024,DOCUMENT_MIME=new Set(['image/jpeg','image/png','image/webp','image/heic','image/heif']);
function documentMime(file){const direct=String(file?.type||'').toLowerCase();if(DOCUMENT_MIME.has(direct))return direct;const ext=String(file?.name||'').toLowerCase().match(/\.([a-z0-9]+)$/)?.[1]||'';return({jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp',heic:'image/heic',heif:'image/heif'})[ext]||''}
function validateDocumentFile(file){if(!file)return'';if(file.size>DOCUMENT_MAX_BYTES)return'Фото документа має бути до 8 МБ';if(!documentMime(file))return'Підтримуються JPG, PNG, WEBP або HEIC';return''}
async function documentRequest(action,{phone,file}={},retry=true){let session=getSession();if(!session?.access_token){const e=new Error('Сесія завершена');e.status=401;throw e}const upload=action==='upload',headers={Authorization:`Bearer ${session.access_token}`,apikey:KEY};let body;if(upload){const issue=validateDocumentFile(file);if(issue)throw new Error(issue);headers['Content-Type']=documentMime(file);headers['x-client-phone']=normalizePhone(phone);headers['x-file-name']=encodeURIComponent(String(file?.name||'document'));body=file}else{headers['Content-Type']='application/json';body=JSON.stringify({phone:normalizePhone(phone)})}let response;try{response=await fetch(`${DOCUMENT_API}?action=${encodeURIComponent(action)}`,{method:'POST',headers,body})}catch{const e=new Error(navigator.onLine?'Не вдалося завантажити документ':'Немає інтернету. Документ не завантажено.');e.status=0;throw e}if(response.status===401&&retry){await refresh();return documentRequest(action,{phone,file},false)}const data=await response.json().catch(()=>({error:'service_error'}));if(!response.ok){const labels={forbidden:'Немає доступу до документів',invalid_customer:'Перевірте номер телефону клієнта',customer_not_found:'Спочатку збережіть клієнта',invalid_file_type:'Підтримуються JPG, PNG, WEBP або HEIC',file_too_large:'Фото документа має бути до 8 МБ',service_error:'Не вдалося обробити фото документа'};const e=new Error(labels[data.error]||data.error||'Помилка документа');e.status=response.status;throw e}return data}
function documentUploadHtml({hasPhoto=false,name='',compact=false}={}){return`<div class="document-photo-upload wide ${compact?'compact':''}" data-document-upload><div class="document-photo-head"><div><b>Фото документа</b><small>Приватне фото · доступне тільки в адмінці</small></div><span class="${hasPhoto?'stored':''}" data-document-state>${hasPhoto?'Фото збережено':'Фото не додано'}</span></div><label class="document-photo-picker"><input type="file" data-document-file accept="image/jpeg,image/png,image/webp,image/heic,image/heif" hidden><span>${hasPhoto?'Замінити фото':'Додати фото'}</span><small>JPG / PNG / WEBP / HEIC · до 8 МБ</small></label><div class="document-local-preview" data-document-preview hidden><img alt="Попередній перегляд документа"><div><b data-document-name>${h(name||'Фото документа')}</b><small>Буде завантажено після збереження</small></div></div></div>`}
function bindDocumentPicker(root){const box=root?.querySelector?.('[data-document-upload]');if(!box)return null;const input=box.querySelector('[data-document-file]'),preview=box.querySelector('[data-document-preview]'),img=preview?.querySelector('img'),name=preview?.querySelector('[data-document-name]'),state=box.querySelector('[data-document-state]');let objectUrl='';input?.addEventListener('change',()=>{const file=input.files?.[0]||null,issue=validateDocumentFile(file);if(issue){toast(issue);input.value='';return}if(objectUrl)URL.revokeObjectURL(objectUrl);if(!file){if(preview)preview.hidden=true;return}objectUrl=URL.createObjectURL(file);if(img)img.src=objectUrl;if(name)name.textContent=file.name||'Фото документа';if(preview)preview.hidden=false;if(state){state.textContent='Нове фото вибрано';state.className='selected'}});return{file:()=>input?.files?.[0]||null,setStored:(stored,label='')=>{if(!state)return;state.textContent=stored?(label||'Фото збережено'):'Фото не додано';state.className=stored?'stored':''},destroy:()=>{if(objectUrl)URL.revokeObjectURL(objectUrl)}}}

function toast(t,type='info'){const e=document.createElement('div');e.className=`toast ${safeToken(type)}`;e.setAttribute('role','status');e.setAttribute('aria-live','polite');e.textContent=t;document.body.append(e);requestAnimationFrame(()=>e.classList.add('show'));setTimeout(()=>{e.classList.remove('show');setTimeout(()=>e.remove(),180)},2800)}
function tval(b,k){const s=getSlots();return b?.extras?.[k]||('pickup_time'===k?(b.pickup_window==='morning'?s.morningStart:s.eveningStart):(b.return_window==='morning'?s.morningEnd:s.eveningEnd))}
function isHistoricalPhone(value){return /^history:[0-9a-f]{8,}$/i.test(String(value||''))}
function displayPhone(value){return isHistoricalPhone(value)?'—':String(value||'—')}
function isPuzzi(b){return Number(CORE.productMeta(b.product_code)?.resources?.puzzi||0)>0}
function chem(b){const c=b.extras?.chemistry||b.extras?.finance||{};return{used:Number(c.used_packets||0),story:c.story_mention===true}}
function calc(b,override={}){const historical=isHistoricalBooking(b);if(historical){const expenses=Math.max(0,Number(b.total_amount||b.base_amount||0));return{used:0,story:false,pre:0,securityDeposit:0,depositPaid:false,depositReturned:true,chemistry:0,extraItems:0,discountAmount:0,baseBeforeDiscount:expenses,baseAmount:expenses,cancelled:false,retainedPrepayment:0,expenses,received:expenses,refund:0,due:0,historical:true}}const c=chem(b),used=override.used??c.used,story=override.story??c.story,pre=b.prepayment_paid===false?0:Number(b.prepayment_amount||200),securityDeposit=Math.max(0,Number(override.depositAmount??b.deposit_amount??depositFor(b.product_code,b.start_date,b.return_date,b.pickup_window||'morning',b.return_window||'evening'))||0),depositPaid=override.depositPaid??(b.deposit_paid===true),depositReturned=override.depositReturned??(b.deposit_returned===true),chemistry=isPuzzi(b)?Math.max(used-(story?2:0),0)*Number(getCatalog().puzziPacketPrice||50):0,extraItems=extrasTotal(b),baseBeforeDiscount=rawRentalBase(b),baseAmount=Math.max(0,Number((override.baseAmount??b.base_amount)||0)),discountAmount=Math.max(0,baseBeforeDiscount-baseAmount),cancelled=['cancelled','declined'].includes(b.status),cancelMeta=b.extras?.cancellation&&typeof b.extras.cancellation==='object'?b.extras.cancellation:{},retainedPrepayment=b.status==='cancelled'&&pre>0&&cancelMeta.prepayment_refundable===false?Math.min(pre,Math.max(0,Number(cancelMeta.prepayment_retained||pre))):0,expenses=cancelled?retainedPrepayment:baseAmount+Number(b.delivery_amount||0)+extraItems+chemistry,received=pre+(depositPaid?securityDeposit:0),balance=received-expenses;return{used,story,pre,securityDeposit,depositPaid,depositReturned,chemistry,extraItems,discountAmount,baseBeforeDiscount,baseAmount,cancelled,retainedPrepayment,expenses,received,refund:cancelled?Math.max(received-retainedPrepayment,0):Math.max(balance,0),due:cancelled?0:Math.max(-balance,0)}}
function pimgs(b){return CORE.productImages(b.product_code)}
function recalcCalendarSlots(days,bookings){const active=(bookings||[]).filter(b=>b.status==='confirmed'||b.status==='issued'||(b.status==='waiting_payment'&&b.hold_expires_at&&new Date(b.hold_expires_at).getTime()>Date.now()));const dayNumber=date=>Math.floor(new Date(`${date}T12:00:00Z`).getTime()/86400000),slotIndex=(date,window)=>dayNumber(date)*2+(window==='evening'?1:0),bookingWindow=(b,kind)=>kind==='start'?(b.pickup_window||slotForTime(tval(b,'pickup_time'))):(b.return_window||slotForTime(tval(b,'return_time'))),bookingIndex=(b,kind)=>slotIndex(kind==='start'?b.start_date:b.return_date,bookingWindow(b,kind));return(days||[]).map(day=>{const resources={};for(const [code,row] of Object.entries(day.resources||{})){const capacity=Number(row.capacity||0),countAt=window=>active.reduce((sum,b)=>{const at=slotIndex(day.date,window),start=bookingIndex(b,'start'),end=bookingIndex(b,'end');if(!(start<=at&&at<end))return sum;const resource=(b.vacleaner_booking_resources||[]).find(r=>r.resource_code===code);return sum+Number(resource?.quantity||0)},0);resources[code]={...row,morning:Math.max(0,capacity-countAt('morning')),evening:Math.max(0,capacity-countAt('evening'))}}return{...day,resources}})}
async function load(){const [b,c,clients,campaigns,referrals]=await Promise.all([invokeData({action:'list'}),invoke({action:'calendar',from:todayIso(),days:14}),invokeData({action:'clients'}),invokeData({action:'campaigns'}).catch(()=>({campaigns:[]})),invoke({action:'referrals_expiring'}).catch(()=>({rewards:[]}))]);state.bookings=b.bookings||[];state.expenses=b.expenses||[];state.calendar=recalcCalendarSlots(c.days||[],state.bookings);state.customers=clients.customers||[];state.campaigns=campaigns.campaigns||[];state.referrals={rewards:referrals.rewards||[]};renderBadges()}
function liveBookingFingerprint(items){return JSON.stringify((items||[]).map(b=>[b.id,b.status,b.updated_at||'',b.hold_expires_at||'',b.prepayment_paid===true,b.deposit_paid===true,b.deposit_returned===true,Number(b.total_amount||0),Number(b.deposit_amount||0),b.start_date,b.return_date,b.extras?.pickup_time||'',b.extras?.return_time||'']))}
function renderAfterLiveSync(){const main=$('.main'),top=main?.scrollTop||0,left=main?.scrollLeft||0;render();requestAnimationFrame(()=>{const current=$('.main');if(current){current.scrollTop=top;current.scrollLeft=left}})}
async function syncBookingsLive({force=false}={}){if(liveBookingSyncBusy||document.visibilityState==='hidden'||!navigator.onLine||!getSession()||$('#layer')?.children.length)return;liveBookingSyncBusy=true;try{const data=await invokeData({action:'list'}),next=data.bookings||[],nextExpenses=data.expenses||[],fingerprint=liveBookingFingerprint(next),changed=fingerprint!==lastLiveBookingFingerprint,expensesChanged=JSON.stringify(nextExpenses)!==JSON.stringify(state.expenses);if(!lastLiveBookingFingerprint)lastLiveBookingFingerprint=liveBookingFingerprint(state.bookings);if(changed||expensesChanged||force){state.bookings=next;state.expenses=nextExpenses;lastLiveBookingFingerprint=fingerprint;if(state.calendar.length)state.calendar=recalcCalendarSlots(state.calendar,state.bookings);renderBadges();if(state.view==='calendar'){const calendar=await invoke({action:'calendar',from:todayIso(),days:14});state.calendar=recalcCalendarSlots(calendar.days||[],state.bookings)}if(['bookings','upcoming','calendar','analytics','finances','chemistry'].includes(state.view))renderAfterLiveSync()}}catch(error){if(error?.status===401)return;console.warn('vacleaner_live_sync_failed',error?.message||error)}finally{liveBookingSyncBusy=false}}
function startLiveBookingSync(){clearInterval(liveBookingSyncTimer);lastLiveBookingFingerprint=liveBookingFingerprint(state.bookings);liveBookingSyncTimer=window.setInterval(()=>syncBookingsLive(),LIVE_BOOKING_SYNC_MS);const syncNow=()=>{if(document.visibilityState==='visible')syncBookingsLive({force:false})};document.addEventListener('visibilitychange',syncNow);window.addEventListener('focus',syncNow);window.addEventListener('pageshow',syncNow)}
const ico={book:'<svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/></svg>',cal:'<svg viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="17" rx="2"/><path d="M8 2v4M16 2v4M3 9h18"/></svg>',msg:'<svg viewBox="0 0 24 24"><path d="M21 15a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4z"/></svg>',tech:'<svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="3"/><path d="M7 9h10M8 19v2M16 19v2"/></svg>',clients:'<svg viewBox="0 0 24 24"><circle cx="9" cy="8" r="3"/><circle cx="17" cy="9" r="2"/><path d="M3 20c0-4 2-6 6-6s6 2 6 6M15 15c3 0 5 2 5 5"/></svg>',chart:'<svg viewBox="0 0 24 24"><path d="M4 20V10M10 20V4M16 20v-7M22 20V7"/></svg>',chem:'<svg viewBox="0 0 24 24"><path d="M9 3h6M10 3v5l-5 9a3 3 0 0 0 3 4h8a3 3 0 0 0 3-4l-5-9V3"/><path d="M7 16h10"/></svg>',gear:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2.8 2.8-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6v.2h-4V21a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1L4.2 17l.1-.1a1.7 1.7 0 0 0 .3-1.9A1.7 1.7 0 0 0 3 14H2.8v-4H3a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9L4.2 7 7 4.2l.1.1a1.7 1.7 0 0 0 1.9.3A1.7 1.7 0 0 0 10 3V2.8h4V3a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1L19.8 7l-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.6 1h.2v4H21a1.7 1.7 0 0 0-1.6 1z"/></svg>',campaign:'<svg viewBox="0 0 24 24"><path d="M4 13V9l12-5v14L4 13z"/><path d="M8 14l2 6H7l-2-7M18 8c1 1 1 3 0 4"/></svg>',wallet:'<svg viewBox="0 0 24 24"><path d="M4 7.5A2.5 2.5 0 0 1 6.5 5H19v14H6.5A2.5 2.5 0 0 1 4 16.5z"/><path d="M4 8h15M15 11h6v5h-6a2.5 2.5 0 0 1 0-5z"/></svg>',more:'<svg viewBox="0 0 24 24"><circle cx="5" cy="12" r="1.4"/><circle cx="12" cy="12" r="1.4"/><circle cx="19" cy="12" r="1.4"/></svg>'};
function adminLoginEmail(value){const login=String(value||'').trim().toLowerCase();if(login==='vacleaner'||login==='annanevidoma')return 'vahome.aroma@gmail.com';return login}
