  const menus=$$('.campaign-more');menus.forEach(details=>{const summary=details.querySelector('summary');summary?.setAttribute('aria-expanded',details.open?'true':'false');details.addEventListener('toggle',()=>{if(details.open)closeCampaignMenus(details);summary?.setAttribute('aria-expanded',details.open?'true':'false')})});if(!campaignMenuEventsBound){campaignMenuEventsBound=true;document.addEventListener('pointerdown',event=>{if(!event.target.closest('.campaign-more'))closeCampaignMenus()});document.addEventListener('keydown',event=>{if(event.key==='Escape')closeCampaignMenus()})}
