  $$('[data-campaign-archive]').forEach(btn=>btn.onclick=()=>{btn.closest('details')?.removeAttribute('open');const campaign=state.campaigns.find(c=>c.id===btn.dataset.campaignArchive);if(campaign)confirmCampaignAction(campaign,'archive')});
  $$('[data-campaign-delete]').forEach(btn=>btn.onclick=()=>{btn.closest('details')?.removeAttribute('open');const campaign=state.campaigns.find(c=>c.id===btn.dataset.campaignDelete);if(campaign)confirmCampaignAction(campaign,'delete')});
  $$('[data-campaign-codes]').forEach(btn=>btn.onclick=()=>{const campaign=state.campaigns.find(c=>c.id===btn.dataset.campaignCodes);if(!campaign)return;const codes=campaign.codes||[];modal(`<div class="modal-form campaign-codes-modal"><header><div><small>${h(campaignTypeLabel(campaign.campaign_type))}</small><h2>${h(campaign.name)}</h2><p>${codes.length} кодів у поточній вибірці.</p></div><button class="close" type="button" data-close>×</button></header><div class="campaign-code-list">${codes.map(row=>`<div><code>${h(row.code)}</code><span>${h(row.customer_phone||'загальний код')}</span></div>`).join('')||'<p>Кодів немає.</p>'}</div><footer><button class="btn" type="button" id="copyCampaignCodes">Скопіювати</button><button class="btn primary" type="button" data-close>Готово</button></footer></div>`);$('#copyCampaignCodes')?.addEventListener('click',async()=>{const text=codes.map(row=>`${row.code}${row.customer_phone?' · '+row.customer_phone:''}`).join('\n');try{await navigator.clipboard.writeText(text);toast('Коди скопійовано','success')}catch{toast('Не вдалося скопіювати')}})});
