function auth(){const mount=$('#adminMount');if(!mount)throw new Error('admin_mount_missing');document.body.classList.remove('admin-shell-ready');$('#layer').innerHTML='';setMarkup(mount,`<main class="auth"><section class="card auth-card"><div class="auth-brand"><div class="brand-mark">VA</div><div class="brand-copy"><strong>VAcleaner</strong><span>Manager</span></div></div><h1>Вхід в адмінку</h1><p>Бронювання, календар, клієнти й фінанси в одному місці.</p><form id="authForm"><label class="field"><span>Логін</span><input name="login" value="vacleaner" required></label><label class="field"><span>Пароль</span><input name="password" type="password" required></label><label class="switch wide auth-remember"><input name="remember" type="checkbox" ${sessionPersistent()?'checked':''}><span><b>Запам’ятати цей пристрій</b><small>У встановленій PWA вхід збережеться на цьому пристрої.</small></span></label><p class="error hidden" id="authError"></p><button class="btn primary" type="submit">Увійти</button></form></section></main>`);if(pwaWaitingWorker)showPwaUpdatePrompt(pwaWaitingWorker);$('#authForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,err=$('#authError'),loginAlias=String(f.login.value||'').trim().toLowerCase(),email=adminLoginEmail(loginAlias),password=f.password.value,remember=f.remember.checked,btn=f.querySelector('[type=submit]');err.classList.add('hidden');btn.disabled=true;try{const session=await login(email,password);if(loginAlias==='vacleaner'||loginAlias==='annanevidoma')localStorage.setItem(ADMIN_ALIAS_KEY,loginAlias);saveSession(session,remember);if(document.activeElement instanceof HTMLElement)document.activeElement.blur();syncPwaViewport();await new Promise(resolve=>setTimeout(resolve,40));await start();syncPwaViewport();window.scrollTo(0,0)}catch(x){btn.disabled=false;err.textContent=x.message;err.classList.remove('hidden')}}}
async function start(){if(!pendingBookingId)pendingBookingId=bookingIdFromUrl();state.session=getSession();if(!state.session)return auth();shell();renderLoading();try{await loadGlobalSlots();await load();state.lastError=null;render();openPendingBooking();syncPushOnLaunch();startLiveBookingSync()}catch(e){if(e.status===401){clearSession();auth()}else renderLoadError(e)}}
